// The wordmark path in the SVG's 1485x145 viewBox space; callers apply their
// own placement transform. The first glyph's counter uses even-odd winding.
inline const juce::Path& logoArtwork() {
    static const juce::Path path = [] {
        juce::Path p;
        const char* s = kLogoPathData;
        const auto number = [&s] {
            while (*s == ' ')
                ++s;
            char* end = nullptr;
            const float v = std::strtof(s, &end);
            s = end;
            return v;
        };
        while (*s != '\0') {
            const char command = *s++;
            if (command == 'M')
                p.startNewSubPath(number(), number());
            else if (command == 'L')
                p.lineTo(number(), number());
            else if (command == 'C')
                p.cubicTo(number(), number(), number(), number(), number(), number());
            else if (command == 'Z')
                p.closeSubPath();
        }
        p.setUsingNonZeroWinding(false);
        return p;
    }();
    return path;
}
